def resolve(path, cwd, links):
    # Normalize input path to absolute
    if path.startswith('/'):
        current = '/'
        components = path.split('/')[1:]
    else:
        current = cwd
        components = path.split('/')

    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        comp = components[i]

        # Skip empty components and '.'
        if comp == '' or comp == '.':
            i += 1
            continue

        # Handle '..'
        if comp == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        # Append component to current path
        if current == '/':
            new_path = '/' + comp
        else:
            new_path = current + '/' + comp

        # Check if this path is a symlink
        if new_path in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[new_path]

            # Resolve symlink target
            if target.startswith('/'):
                current = '/'
                new_components = target.split('/')[1:]
            else:
                # Target is relative to the directory containing the link
                if current == '/':
                    current = '/'
                else:
                    current = current.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                new_components = target.split('/')

            # Replace the current component and remaining components with new ones
            components = new_components + components[i+1:]
            i = 0
            continue

        # No symlink, just move to this path
        current = new_path
        i += 1

    # Clean up trailing slash (except for '/')
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

